CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),paused INTEGER NOT NULL DEFAULT 0,lock_token TEXT,lock_until INTEGER NOT NULL DEFAULT 0,cleanup_at INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY,enabled INTEGER NOT NULL,rights TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chats(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL DEFAULT '',telegram_id TEXT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'private',mode TEXT NOT NULL DEFAULT 'off',consent INTEGER NOT NULL DEFAULT 0,until_at INTEGER NOT NULL DEFAULT 0,instruction TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 0,last_incoming INTEGER NOT NULL DEFAULT 0,last_manual INTEGER NOT NULL DEFAULT 0,pause_until INTEGER NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '',UNIQUE(connection_id,telegram_id));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,scope TEXT NOT NULL,role TEXT NOT NULL,body TEXT NOT NULL,at INTEGER NOT NULL,manual INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS messages_scope_at ON messages(scope,at);
CREATE TABLE IF NOT EXISTS facts(scope TEXT NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,source TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE IF NOT EXISTS inbox(id TEXT PRIMARY KEY,scope TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',at INTEGER NOT NULL,not_before INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS inbox_pending ON inbox(state,not_before,at);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,scope TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',revision INTEGER NOT NULL,expires_at INTEGER NOT NULL,at INTEGER NOT NULL,UNIQUE(event_id,kind,scope));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,scope TEXT NOT NULL,method TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',mode TEXT NOT NULL DEFAULT 'owner',revision INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL,not_before INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,message_id TEXT,at INTEGER NOT NULL,error TEXT);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(state,not_before,at);
CREATE TABLE IF NOT EXISTS usage(day TEXT PRIMARY KEY,requests INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS providers(name TEXT PRIMARY KEY,blocked_until INTEGER NOT NULL DEFAULT 0,kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,at INTEGER NOT NULL);
